// Fiyat hesaplayıcının saf mantığı: hacim kademeleri, dönemlik toplam, tasarruf, önerilen plan ve yazımlar.
// Para hesabı kuruş tamsayısıyla ABACUS'un `math` ve `money.toMinor` araçlarıyla yapılır; fiyat tablosu uygulamadan gelir.
import { math, money } from "@snn/abacus-core";
import { formatMoney, formatNumber, formatPercent } from "../lib/chart-format";

export type BillingPeriod = "month" | "year";
export interface PriceTier { /** Bu koltuk sayısından itibaren geçerli koltuk başı aylık fiyat (TRY). */ fromSeats: number; price: number }
export interface PlanFeature { label: string; /** Yalnız bu koltuk sayısından itibaren listede. */ fromSeats?: number; /** Yalnız bu koltuk sayısına kadar listede. */ toSeats?: number }
export interface PricingPlan {
  key: string;
  name: string;
  description?: string;
  /** Hacim kademeleri, artan `fromSeats` sırasıyla; ilki taban fiyattır. */
  tiers: PriceTier[];
  /** Plan bu koltuk sayısından büyük seçime satılmaz (sınırlı plan). */
  maxSeats?: number;
  /** Plan "önerilen" sayılacağı koltuk aralığı: [en az, en çok]; en çok yoksa üst sınırsız. */
  fitsSeats: [number, number | null];
  features: PlanFeature[];
}

/** Koltuk sayısına uyan kademenin koltuk başı aylık fiyatı (kuruş tamsayısı). */
export function seatPriceMinor(plan: PricingPlan, seats: number): number {
  const tier = [...plan.tiers].sort((a, b) => a.fromSeats - b.fromSeats).filter(item => item.fromSeats <= seats).pop() ?? plan.tiers[0];
  return money.toMinor(tier?.price ?? 0) ?? 0;
}

/** Dönem için koltuk başı aylık fiyat: yıllıkta indirim uygulanır, kuruşa yuvarlanır. */
export function periodSeatMinor(plan: PricingPlan, seats: number, period: BillingPeriod, yearlyDiscount: number): number {
  const monthly = seatPriceMinor(plan, seats);
  return period === "year" ? math.round(math.mul(monthly, (100 - yearlyDiscount) / 100), 0) : monthly;
}

/** Dönemlik toplam (kuruş): koltuk başı aylık fiyat × koltuk × ay sayısı. */
export function totalMinor(plan: PricingPlan, seats: number, period: BillingPeriod, yearlyDiscount: number): number {
  return math.mul(math.mul(periodSeatMinor(plan, seats, period, yearlyDiscount), seats), period === "year" ? 12 : 1);
}

/** Yıllık ödemeyle tasarruf (kuruş): 12 aylık aylık-ödeme toplamı eksi yıllık toplam. */
export const savingsMinor = (plan: PricingPlan, seats: number, yearlyDiscount: number) => totalMinor(plan, seats, "month", yearlyDiscount) * 12 - totalMinor(plan, seats, "year", yearlyDiscount);

/** Hacim indirimi: koltuk başı fiyatın tabandan farkı (kuruş); indirim yoksa 0. */
export function volumeDiscountMinor(plan: PricingPlan, seats: number): number {
  const base = money.toMinor(plan.tiers[0]?.price ?? 0) ?? 0;
  return Math.max(base - seatPriceMinor(plan, seats), 0);
}

/** Plan bu seçime satılıyor mu (sınırlı plan üst sınırı aştıysa hayır). */
export const sellable = (plan: PricingPlan, seats: number) => plan.maxSeats === undefined || seats <= plan.maxSeats;

/** Koltuk sayısına en uygun plan: aralığı kapsayan ilk plan; hiçbiri değilse sonuncu. */
export function recommendedKey(plans: PricingPlan[], seats: number): string | undefined {
  const fit = plans.find(plan => seats >= plan.fitsSeats[0] && (plan.fitsSeats[1] === null || seats <= plan.fitsSeats[1]));
  return (fit ?? plans[plans.length - 1])?.key;
}

/** Koltuk sayısına göre listeye giren özellikler. */
export const visibleFeatures = (plan: PricingPlan, seats: number) => plan.features.filter(feature => (feature.fromSeats === undefined || seats >= feature.fromSeats) && (feature.toSeats === undefined || seats <= feature.toSeats));

export const minorMoney = (minor: number) => formatMoney(math.div(minor, 100) ?? 0, 2);
/** Kuruş tamsayısı → ana birim (sayaç için). */
export const majorOf = (minor: number) => math.div(minor, 100) ?? 0;
export const seatsText = (seats: number) => `${formatNumber(seats, 0)} koltuk`;
export const percentText = (percent: number) => formatPercent(percent, 0);
export const periodWord = (period: BillingPeriod) => period === "year" ? "yıllık" : "aylık";

/** Kart altı: "yıllık olarak ödenir, 20 koltuk için". */
export const paymentNote = (period: BillingPeriod, seats: number) => `${period === "year" ? "Yıllık olarak ödenir" : "Aylık olarak ödenir"}, ${seatsText(seats)} için`;
/** Sınırlı plan uyarısı: "Bu plan en çok 10 koltuğa uygun. Siz 20 koltuk seçtiniz." */
export const limitMessage = (max: number, seats: number) => `Bu plan en çok ${formatNumber(max, 0)} koltuğa uygun. Siz ${seatsText(seats)} seçtiniz.`;

.root { container-type: inline-size; display: grid; min-width: 0; gap: var(--space-5); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); }
.header { display: grid; gap: var(--space-1); text-align: center; }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }
.description { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); }
.controls { display: grid; gap: var(--space-4); justify-items: center; }
.seatBox { display: grid; gap: var(--space-2); width: min(100%, 30rem); }
.seatLabel { color: var(--text-secondary); font-size: var(--text-sm); text-align: center; }
.seatRow { display: flex; align-items: center; justify-content: center; gap: var(--space-5); }
.seatCount { display: inline-flex; align-items: baseline; gap: var(--space-2); font-family: var(--font-display); font-size: var(--text-4xl); letter-spacing: var(--tracking-display); line-height: var(--leading-display); font-variant-numeric: tabular-nums; }
.seatCount small { color: var(--text-secondary); font-family: var(--font-body); font-size: var(--text-sm); letter-spacing: 0; }
.step { width: 2.75rem; height: 2.75rem; border: 1px solid var(--border-strong); border-radius: 50%; background: var(--surface); color: var(--foreground); font-size: var(--text-lg); cursor: pointer; }
.step:hover:not(:disabled) { background: var(--surface-muted); }
.step:disabled { color: var(--text-muted); cursor: default; opacity: .5; }
.slider { width: 100%; min-height: 2.75rem; margin: 0; accent-color: var(--accent); cursor: pointer; }
.slider:focus-visible, .step:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.marks { position: relative; height: 1rem; margin-top: calc(var(--space-2) * -1); color: var(--text-muted); font-size: var(--text-xs); }
.marks span { position: absolute; transform: translateX(-50%); white-space: nowrap; }
.marks span:first-child { transform: none; }
.cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-3); }
.card { position: relative; display: grid; align-content: start; gap: var(--space-2); min-width: 0; padding: var(--space-5); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface-raised); }
.frame { position: absolute; inset: -1px; z-index: 0; border: 2px solid var(--accent); border-radius: var(--radius-panel); pointer-events: none; }
.card > *:not(.frame) { position: relative; z-index: 1; }
.cardTop { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); min-height: 1.75rem; }
.cardTop h4 { margin: 0; font-size: var(--text-lg); font-weight: 500; }
.badge { padding: 2px var(--space-3); border-radius: var(--radius-pill); background: var(--accent); color: var(--accent-foreground); font-size: var(--text-xs); font-weight: 500; }
.planNote { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); }
.price { display: flex; align-items: baseline; gap: var(--space-2); margin: var(--space-2) 0 0; font-family: var(--font-display); font-size: var(--text-3xl); letter-spacing: var(--tracking-display); font-variant-numeric: tabular-nums; }
.price small { color: var(--text-secondary); font-family: var(--font-body); font-size: var(--text-xs); letter-spacing: 0; }
.totalLine { margin: 0; font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.totalLine span { color: var(--text-secondary); display: block; font-size: var(--text-xs); }
.discount { margin: 0; color: var(--success); font-size: var(--text-xs); }
.limit { display: grid; gap: var(--space-3); padding: var(--space-3) 0; color: var(--text-secondary); font-size: var(--text-sm); }
.limit p { margin: 0; }
.features { display: grid; gap: var(--space-1); margin: var(--space-2) 0 0; padding: var(--space-3) 0 0; border-top: 1px solid var(--border-subtle); list-style: none; font-size: var(--text-sm); }
.summary { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: var(--space-5); padding: var(--space-4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-muted); }
.summaryTitle { margin: 0; font-size: var(--text-base); font-weight: 500; }
.summaryNote { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.savings { margin: 2px 0 0; color: var(--success); font-size: var(--text-sm); }
.summaryTotal { display: inline-flex; align-items: baseline; gap: var(--space-2); font-family: var(--font-display); font-size: var(--text-2xl); letter-spacing: var(--tracking-display); font-variant-numeric: tabular-nums; }
.summaryTotal small { color: var(--text-secondary); font-family: var(--font-body); font-size: var(--text-sm); letter-spacing: 0; }
.startBox { display: grid; gap: var(--space-1); justify-items: end; }
.status { margin: 0; min-height: 1.25rem; color: var(--text-secondary); font-size: var(--text-xs); }
.status[data-tone="error"] { color: var(--danger); }
.empty { margin: 0; padding: var(--space-8) 0; color: var(--text-muted); text-align: center; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@container (max-width: 860px) { .cards { grid-template-columns: minmax(0, 1fr); } .summary { grid-template-columns: minmax(0, 1fr); justify-items: start; } .startBox { justify-items: start; } }
@container (max-width: 560px) { .root { padding: var(--space-4); } .title { font-size: var(--text-2xl); } .seatCount { font-size: var(--text-3xl); } }
@container (max-width: 360px) { .seatRow { gap: var(--space-2); } }

"use client";

import { useId, useMemo, useState } from "react";
import { AnimatePresence, LayoutGroup, motion } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Button } from "../button/button";
import { useReducedMotionSafe } from "../lib/viz-utils";
import SegmentedControl from "../segmented-control/segmented-control";
import { Skeleton } from "../skeleton/skeleton";
import { limitMessage, majorOf, minorMoney, paymentNote, percentText, periodSeatMinor, periodWord, recommendedKey, savingsMinor, sellable, seatsText, totalMinor, visibleFeatures, volumeDiscountMinor, type BillingPeriod, type PlanFeature, type PriceTier, type PricingPlan } from "./pricing-calculator-format";
import styles from "./pricing-calculator.module.css";

export type { BillingPeriod, PlanFeature, PriceTier, PricingPlan };
export interface TrialSelection { plan: string; seats: number; period: BillingPeriod }

/** Koltuk (kullanıcı) başına fiyatlanan bir ürün için ekip büyüklüğünü kaydırıcıyla seçtirmek, aylık / yıllık fiyatları, hacim indirimini ve önerilen planı canlı göstermek için kullanın; ölçüme göre fiyatlanan ürün için kullanıma göre fiyat hesaplayıcı daha doğrudur. */
export interface PricingCalculatorProps {
  /** Planlar, küçükten büyüğe (en çok üç). Fiyat tablosunu uygulama verir. */
  plans: PricingPlan[];
  /** Kaydırıcının sabit koltuk durakları, artan: [1, 5, 10, 20, 50, 100]. */
  stops: number[];
  defaultSeats?: number;
  /** Yıllık ödeme indirimi (yüzde), örneğin 20. */
  yearlyDiscount?: number;
  title?: string;
  description?: string;
  /** "Denemeyi başlat": reddederse (Promise) satır içi "Başlatılamadı" yazılır ve yeniden denenir. */
  onStartTrial: (selection: TrialSelection) => Promise<void>;
  loading?: boolean;
}

export function PricingCalculator({ plans, stops, defaultSeats, yearlyDiscount = 20, title = "Kullandığınız koltuk kadar ödeyin", description, onStartTrial, loading = false }: PricingCalculatorProps) {
  const reduced = useReducedMotionSafe();
  const baseId = useId();
  const [index, setIndex] = useState(() => Math.max(0, stops.indexOf(defaultSeats ?? stops[Math.min(2, stops.length - 1)] ?? 1)));
  const [period, setPeriod] = useState<BillingPeriod>("month");
  const [picked, setPicked] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<{ tone: "ok" | "error"; text: string } | null>(null);
  const [announce, setAnnounce] = useState("");
  const seats = stops[index] ?? 1;
  const recommended = recommendedKey(plans, seats);
  const chosenKey = picked && plans.some(plan => plan.key === picked && sellable(plan, seats)) ? picked : recommended;
  const chosen = plans.find(plan => plan.key === chosenKey);
  const spring = reduced ? { duration: 0 } : { type: "spring" as const, visualDuration: .4, bounce: .08 };

  const setSeatsAt = (next: number) => { const bounded = Math.min(Math.max(next, 0), stops.length - 1); setIndex(bounded); setMessage(null); setAnnounce(seatsText(stops[bounded] ?? 1)); };
  const changePeriod = (value: string) => { setPeriod(value as BillingPeriod); setAnnounce(value === "year" ? "Yıllık ödeme" : "Aylık ödeme"); };
  const choose = (key: string) => { setPicked(key); setAnnounce(`${plans.find(plan => plan.key === key)?.name} planı seçildi`); };
  const start = async () => {
    if (!chosen) return;
    setBusy(true); setMessage(null);
    try { await onStartTrial({ plan: chosen.key, seats, period }); setMessage({ tone: "ok", text: "Deneme başlatıldı" }); setAnnounce("Deneme başlatıldı"); }
    catch { setMessage({ tone: "error", text: "Başlatılamadı" }); }
    finally { setBusy(false); }
  };

  // Plan sınırları: kaydırıcı altında her planın başladığı durak.
  const marks = useMemo(() => plans.map(plan => ({ key: plan.key, name: plan.name, at: Math.max(0, stops.findIndex(stop => stop >= plan.fitsSeats[0])) })), [plans, stops]);

  if (loading || !plans.length) return <section className={styles.root} aria-busy={loading || undefined}>{loading ? <Skeleton label="Planlar yükleniyor" lines={6} /> : <p className={styles.empty}>Plan verisi yok.</p>}</section>;

  const total = chosen ? totalMinor(chosen, seats, period, yearlyDiscount) : 0;
  const seatPrice = chosen ? periodSeatMinor(chosen, seats, period, yearlyDiscount) : 0;
  const saved = chosen && period === "year" ? savingsMinor(chosen, seats, yearlyDiscount) : 0;

  return <section className={styles.root} data-reduced={reduced || undefined} aria-label={title}>
    <header className={styles.header}><h3 className={styles.title}>{title}</h3>{description && <p className={styles.description}>{description}</p>}</header>

    <div className={styles.controls}>
      <div className={styles.seatBox}>
        <label htmlFor={`${baseId}-seats`} className={styles.seatLabel}>Ekip büyüklüğü</label>
        <div className={styles.seatRow}>
          <button type="button" className={styles.step} onClick={() => setSeatsAt(index - 1)} disabled={index === 0} aria-label="Koltuk sayısını azalt">−</button>
          <span className={styles.seatCount} aria-hidden="true"><AnimatedCounter value={seats} /><small>koltuk</small></span>
          <button type="button" className={styles.step} onClick={() => setSeatsAt(index + 1)} disabled={index === stops.length - 1} aria-label="Koltuk sayısını artır">+</button>
        </div>
        <input id={`${baseId}-seats`} className={styles.slider} type="range" min={0} max={stops.length - 1} step={1} value={index} aria-valuetext={seatsText(seats)} onChange={event => setSeatsAt(Number(event.target.value))} />
        <div className={styles.marks} aria-hidden="true">{marks.map(mark => <span key={mark.key} style={{ left: `${stops.length > 1 ? (mark.at / (stops.length - 1)) * 100 : 0}%` }}>{mark.name}</span>)}</div>
      </div>
      <SegmentedControl label="Ödeme dönemi" value={period} onValueChange={changePeriod} options={[{ value: "month", label: "Aylık" }, { value: "year", label: `Yıllık · ${percentText(yearlyDiscount)} tasarruf` }]} />
    </div>

    <LayoutGroup id={baseId}>
      <div className={styles.cards}>
        {plans.map(plan => {
          const ok = sellable(plan, seats), isRec = plan.key === recommended, isChosen = plan.key === chosenKey;
          const perSeat = periodSeatMinor(plan, seats, period, yearlyDiscount), discount = volumeDiscountMinor(plan, seats);
          return <article key={plan.key} className={styles.card} data-chosen={isChosen || undefined} aria-label={plan.name}>
            {isChosen && <motion.span layoutId="frame" className={styles.frame} transition={spring} aria-hidden="true" />}
            <div className={styles.cardTop}><h4>{plan.name}</h4>{isRec && ok && <motion.span layoutId="badge" className={styles.badge} transition={spring}>Önerilen</motion.span>}</div>
            {plan.description && <p className={styles.planNote}>{plan.description}</p>}
            {ok ? <>
              <p className={styles.price}><span aria-label={`koltuk başına ${minorMoney(perSeat)}`}><AnimatedCounter value={majorOf(perSeat)} decimals={2} prefix="₺" /></span><small>koltuk / ay</small></p>
              <p className={styles.totalLine}><b>{minorMoney(totalMinor(plan, seats, period, yearlyDiscount))}</b> <span>{paymentNote(period, seats)}</span></p>
              {discount > 0 && <p className={styles.discount}>Hacim indirimi: koltuk başı {minorMoney(discount)} daha az</p>}
              <Button size="sm" variant={isChosen ? "primary" : "secondary"} aria-pressed={isChosen} onClick={() => choose(plan.key)}>{isChosen ? "Seçildi" : "Bu planı seç"}</Button>
            </> : <div className={styles.limit}>
              <p>{limitMessage(plan.maxSeats ?? 0, seats)}</p>
              <Button size="sm" variant="secondary" onClick={() => { const fit = [...stops].reverse().find(stop => stop <= (plan.maxSeats ?? 0)); if (fit !== undefined) setSeatsAt(stops.indexOf(fit)); }}>{plan.maxSeats} koltuğa dön</Button>
            </div>}
            <ul className={styles.features} aria-label={`${plan.name} özellikleri`}>
              <AnimatePresence initial={false}>
                {visibleFeatures(plan, seats).map(feature => <motion.li key={feature.label} initial={reduced ? false : { height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: reduced ? 0 : .22 }} style={{ overflow: "hidden" }}>✓ {feature.label}</motion.li>)}
              </AnimatePresence>
            </ul>
          </article>;
        })}
      </div>
    </LayoutGroup>

    {chosen && <div className={styles.summary} role="group" aria-label="Seçim özeti">
      <div>
        <p className={styles.summaryTitle}>{chosen.name}, {seatsText(seats)}</p>
        <p className={styles.summaryNote}>{minorMoney(seatPrice)} koltuk başına {periodWord(period)} {period === "year" ? "(aylık karşılığı)" : ""}</p>
        {saved > 0 && <p className={styles.savings}>Tasarruf ettiğiniz: <b>{minorMoney(saved)}</b> / yıl</p>}
      </div>
      <div className={styles.summaryTotal}><AnimatedCounter value={majorOf(total)} decimals={2} prefix="₺" /><small>/ {period === "year" ? "yıl" : "ay"}</small></div>
      <div className={styles.startBox}>
        <Button variant="primary" onClick={start} disabled={busy} loading={busy}>Denemeyi başlat</Button>
        <p className={styles.status} data-tone={message?.tone} role="status">{message?.text ?? ""}</p>
      </div>
    </div>}
    <p className={styles.srOnly} aria-live="polite" aria-atomic="true">{announce}</p>
  </section>;
}

export default PricingCalculator;
